Query:
SELECT fn.source_id,
       fn.node_id,
       fn.start_byte,
       fn.end_byte,
       fn.start_row,
       fn.start_col,
       (fn.end_row - fn.start_row) AS metric
FROM _ast fn
WHERE fn.node_kind IN ('function_declaration','method_declaration')
%s
ORDER BY metric DESC, fn.source_id, fn.start_byte
